mapper.select:
SELECT kd.document_id, kd.current_version_id AS current_document_version_id, dv.version_no, dv.document_name, dv.document_type, dv.document_status, dv.segment_numbers, dv.update_time FROM knowledge_document kd INNER JOIN document_version dv ON dv.document_version_id = kd.current_version_id AND dv.document_id = kd.document_id WHERE kd.is_deleted = 0 AND dv.is_deleted = 0
AND kd.document_user = #{documentUser}
AND dv.document_name LIKE CONCAT('%', #{keyword}, '%')
AND dv.document_status = #{status}
ORDER BY dv.update_time DESC
